            		break;
             */
    }
};

/**
 * @method
 * @name newpreCreateFrame
 * @description 종몰별 관리종목 신규
 * @param {*} arg arg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame = async function(arg) {
    /*
    0:관리종목지정
    1:관리종목사유변경
    4:관리종목지정해제
     */
    switch (arg) {
        case "0":
            const options = {
                id: "ULDSTF70018",
                title: "신종증권 관리종목지정",
                type: "browserPopup",
                width: "820px",
                height: "440px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../digital/ULDSTF70018.gfm", options);
            break;
        case "1":
            const options2 = {
                id: "ULDSTF70099_CHN",
                title: "신종증권 관리종목지정 사유변경",
                type: "browserPopup",
                width: "850px",
                height: "800px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../digital/ULDSTF70099_CHN.gfm", options2);
            break;
        case "4":
            const options3 = {
                id: "ULDSTF70019",
                title: "신종증권 관리종목지정 해제",
                type: "browserPopup",
                width: "830px",
                height: "630px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../digital/ULDSTF70019.gfm", options3);
            break;
    }
};

/**
 * @method
 * @name changeRadioBtn
 * @description change Radio Btn 처리
 * @param {Number} idx idx
 * @returns {void}
 * @hidden N
 */
scwin.changeRadioBtn = function(idx) {
    if (idx === "1") {
        txb_ISUR_CD.setValue("");
        txb_ISUR_NM.setValue("");
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("2");
    } else if (idx === "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_ISUR_CD_1.setValue("2");
        rdo_ISUR_CD_2.setValue("1");
    }
};

/**
 * @method
 * @name reg
 * @description 관리종목 지정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reg = async function() {
    if (rdo_ISUR_CD_1.getValue() === "1") {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    scwin.fn_GetPar = scwin.getParNew;
    scwin.fn_SetPar = undefined;
    // 상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() === "1") {
        await scwin.newCreateFrame("0");
    } else {
        // 종목 기준
        const pIsuCd = dts.getCellData(dts.getRowPosition(), "ISU_CD");
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_change_digital(dts_BZ_CHECK, pIsuCd, "0");
        if (scwin.vChangeBzProcsNo.length === 0) return;
        await scwin.newpreCreateFrame("0");
    }
};

/**
 * @method
 * @name change
 * @description 관리종목 사유변경
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.change = async function() {
    if (rdo_ISUR_CD_1.getValue() === "1") {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    if (dts.getRowCount() === 0) {
        await $c.win.alert("조치할 대상이 없습니다.");
        return;
    }
    scwin.fn_SetPar = undefined;
    // 상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() === "1") {
        scwin.vChangeIsuCd = dts.getCellData(dts.getRowPosition(), "ISU_CD");
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_change_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "1");
        if (scwin.vChangeBzProcsNo.length === 0) return;
        scwin.fn_GetPar = scwin.getParRsnChange2;
    } else {
        // 종목 기준
        scwin.vChangeIsuCd = txb_ISU_CD.getValue();
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_change_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "1");
        if (scwin.vChangeBzProcsNo.length === 0) return;
        scwin.fn_GetPar = scwin.getParRsnChange;
    }
    const options = {
        id: "ULDSTF70099_CHN",
        title: "신종증권 관리종목지정 사유변경",
        type: "browserPopup",
        width: "850px",
        height: "780px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../digital/ULDSTF70099_CHN.gfm", options);
};

/**
 * @method
 * @name changeNew
 * @description 관리종목 사유변경
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeNew = async function() {
    if (rdo_ISUR_CD_1.getValue() === "1") {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    let url = "";
    scwin.fn_SetPar = undefined;
    // 상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() === "1") {
        scwin.fn_GetPar = scwin.getParRsnChange2New;
        url = "../digital/ULDSTF70099_CHN_NEW.gfm";
    } else {
        // 종목 기준
        scwin.vChangeIsuCd = txb_ISU_CD.getValue();
        // 현재 종목의 최종 처리상태를 판단
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_change_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "1");
        if (scwin.vChangeBzProcsNo.length === 0) return;
        scwin.fn_GetPar = scwin.getParRsnChange;
        url = "../digital/ULDSTF70099_CHN.gfm";
    }
    await $c.frame.CreateDialogFrame("DLG_ADMISU_CHANGE", url, "신종증권 관리종목지정 사유변경", 10, 10, 870, 800, "window");
};

/**
 * @method
 * @name release
 * @description 관리종목 해제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.release = async function() {
    if (rdo_ISUR_CD_1.getValue() === "1") {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    let url = "";
    scwin.fn_SetPar = undefined;
    // 상장신청인 기준
    if (rdo_ISUR_CD_2.getValue() === "1") {
        scwin.vChangeIsuCd = dts.getCellData(dts.getRowPosition(), "ISU_CD");
        scwin.fn_GetPar = scwin.getParRelease2;
        url = "../digital/ULDSTF70019_new.gfm";
    } else {
        // 종목 기준
        scwin.vChangeIsuCd = txb_ISU_CD.getValue();
        // 현재 종목의 최종 처리상태를 판단
        scwin.vChangeBzProcsNo = $c.lcd.fn_check_bz_change_digital(dts_BZ_CHECK, scwin.vChangeIsuCd, "4");
        if (scwin.vChangeBzProcsNo.length === 0) return;
        scwin.fn_GetPar = scwin.getParRelease;
        url = "../digital/ULDSTF70019.gfm";
    }
    await $c.frame.CreateDialogFrame("DLG_ADMISU_RELEASE", url, "신종증권 관리종목지정 해제", 10, 10, 830, 630, "window");
};

/**
 * @method
 * @name getParRelease
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParRelease = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_NM.getValue(); // 발행기관코드값
    arrPar[1] = txb_ISU_CD.getValue(); // 발행기관명
    arrPar[2] = ""; // 증권그룹ID
    arrPar[3] = scwin.fr_MktId; // 시장구분코드
    arrPar[4] = ""; // 업무처리번호(신규작성 시 업무처리번호는 없다.)
    arrPar[5] = "4"; // 지정및해제구분코드 , "4" : 해제
    arrPar[6] = scwin.vChangeIsuCd; // 종목코드값
    arrPar[7] = "0"; // 선택 구분(1:종목, 2:발행회사, 3:전체)
    arrPar[8] = scwin.vChangeBzProcsNo; // 지정업무처리번호
    return arrPar.length;
};

